mapper.select:
SELECT p.id, p.name, p.description, p.category_id, p.longitude, p.latitude,
       p.address, p.creator_id, p.status, p.created_at, p.updated_at
FROM place p
INNER JOIN map_place mp ON mp.place_id = p.id AND mp.map_id = #{mapId}
WHERE p.status = 1
  AND p.latitude BETWEEN #{minLat} AND #{maxLat}
  AND p.longitude BETWEEN #{minLng} AND #{maxLng}

SELECT COUNT(*)
FROM map_member mm
INNER JOIN map_place mp ON mp.map_id = mm.map_id AND mp.place_id = #{placeId}
WHERE mm.user_id = #{userId}
  AND mm.role IN ('OWNER', 'EDITOR')

SELECT sm.id, sm.name, mm.role AS myRole
FROM map_place mp
INNER JOIN shared_map sm ON sm.id = mp.map_id
INNER JOIN map_member mm ON mm.map_id = sm.id AND mm.user_id = #{userId}
WHERE mp.place_id = #{placeId}
ORDER BY sm.id ASC

SELECT mp.map_id AS mapId, p.id, p.name, p.description, p.address, p.creator_id AS creatorId, p.category_id AS categoryId, c.name AS categoryName, p.longitude, p.latitude, (SELECT GROUP_CONCAT(pc.content ORDER BY pc.id DESC SEPARATOR ' 丨 ') FROM place_comment pc WHERE pc.map_id = mp.map_id AND pc.place_id = p.id) AS noteDigest FROM map_place mp INNER JOIN place p ON p.id = mp.place_id AND p.status = 1 INNER JOIN place_category c ON c.id = p.category_id WHERE mp.map_id IN
#{mapId}
AND ( p.name LIKE CONCAT('%', #{pattern}, '%') ESCAPE '\\' OR p.description LIKE CONCAT('%', #{pattern}, '%') ESCAPE '\\' OR c.name LIKE CONCAT('%', #{pattern}, '%') ESCAPE '\\' OR EXISTS (SELECT 1 FROM place_comment pc2 WHERE pc2.map_id = mp.map_id AND pc2.place_id = p.id AND pc2.content LIKE CONCAT('%', #{pattern}, '%') ESCAPE '\\') )
AND p.category_id = #{categoryId}
ORDER BY mp.map_id ASC, p.id DESC LIMIT #{limit}

SELECT mp.map_id AS mapId, p.id, p.name, p.description, p.address, p.creator_id AS creatorId, p.category_id AS categoryId, c.name AS categoryName, p.longitude, p.latitude, (SELECT GROUP_CONCAT(pc.content ORDER BY pc.id DESC SEPARATOR ' 丨 ') FROM place_comment pc WHERE pc.map_id = mp.map_id AND pc.place_id = p.id) AS noteDigest FROM map_place mp INNER JOIN place p ON p.id = mp.place_id AND p.status = 1 INNER JOIN place_category c ON c.id = p.category_id WHERE mp.map_id IN
#{mapId}
AND p.id IN
#{placeId}
ORDER BY mp.map_id ASC, p.id DESC
